const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch({
    headless: true,
  });

  const page = await browser.newPage();

  // Set viewport to match poster dimensions
  await page.setViewportSize({ width: 1080, height: 1528 });

  // Load the HTML file
  const htmlPath = path.resolve(__dirname, 'web-summit-lisbon-2026-poster.html');
  const fileUrl = 'file://' + htmlPath;
  await page.goto(fileUrl, { waitUntil: 'networkidle' });

  // Wait for fonts to load and infographic to render
  await page.waitForTimeout(3000);

  // Wait for the infographic container to have content
  await page.waitForFunction(() => {
    const container = document.querySelector('#infographic-container');
    return container && container.children.length > 0;
  }, { timeout: 10000 });

  // Extra wait for rendering to settle
  await page.waitForTimeout(2000);

  // Capture the poster element as PNG
  const poster = await page.$('#poster');
  await poster.screenshot({
    path: path.resolve(__dirname, 'final_poster.png'),
    type: 'png',
  });

  console.log('Poster saved to: ' + path.resolve(__dirname, 'final_poster.png'));

  await browser.close();
})();

